// === Tab: sketch189572 ===
let n = 200,
  w = 1112, 
  h = 834, 
  w2 = w/2, 
  h2 = h/2;
let k1 = 500, 
  k2 = 0.1,
  ks = 25,
  a, b, d, r, f, diam, dx, dy;
float[][] 
  initial_pos,
  pos;

function setup() 
{
    createCanvas(w, h);
	  colorMode(HSB, 255);
    background(-1);
    cursor(CROSS);
    stroke(0,50);
    fill(-1);
    a = b = r = f = diam = 0;
    initial_pos = new Array(n)[2];
    pos = new Array(n)[2];
    for(i = 0; i < n; i++)
    {
        initial_pos[i][0] = pos[i][0] = random(width);
        initial_pos[i][1] = pos[i][1] = random(height);
     }  
}

function draw() 
{       
    update();   
    //copy(g, 0, 0, w, h, (w2-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))>>6, (h2-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))>>6, w, h);
}


function update()
{
    for (i = 0; i < n; i++)
    {
        a = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - pos[i][0];
        b = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - pos[i][1];
        d = a*a + b*b;
        r = k1 / d;
        dx = initial_pos[i][0] - pos[i][0];
        dy = initial_pos[i][1] - pos[i][1];
        pos[i][0] += dx*k2 - a*r;
        pos[i][1] += dy*k2 - b*r;
        f = atan2(b, a);
        diam = ks * f;
        pushMatrix();
          translate(pos[i][0], pos[i][1]);
          rotate(f);
			    fill(i/n*255, 200,255);
          triangle(diam * .66, 0, -diam* .33, -diam * .5, -diam * .33, diam * .5);
        popMatrix(); 
    } 
}

function keyPressed(){
    save('pix.jpg');
}

